// A message built from a payload this workflow was not written for would be
// wrong without anyone noticing, so the payload is checked first. The answer
// to the webhook says what is wrong, and the Airflow task fails on it.
const body = $input.first().json.body;

const isNumber = (value) => typeof value === 'number' && Number.isFinite(value);
const isText = (value) => typeof value === 'string' && value.length > 0;
const isObject = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
const errors = [];
const expect = (ok, message) => { if (!ok) errors.push(message); };

expect(isObject(body), 'the body must be a JSON object');
const digest = isObject(body) ? body : {};
expect(digest.kind === 'daily_digest', 'kind must be "daily_digest"');
expect(digest.schema_version === 1, 'schema_version must be 1');
expect(isText(digest.run_date), 'run_date must be a date');

const rate = digest.exchange_rate;
if (rate !== null) {
  expect(isObject(rate), 'exchange_rate must be an object or null');
  if (isObject(rate)) {
    expect(isText(rate.date), 'exchange_rate.date must be a date');
    expect(isNumber(rate.rate), 'exchange_rate.rate must be a number');
    expect(typeof rate.is_published === 'boolean', 'exchange_rate.is_published must be true or false');
    expect(rate.change === null || isNumber(rate.change), 'exchange_rate.change must be a number or null');
    expect(rate.change_percent === null || isNumber(rate.change_percent), 'exchange_rate.change_percent must be a number or null');
  }
}

const awards = digest.awards;
expect(isObject(awards), 'awards must be an object');
if (isObject(awards)) {
  expect(isText(awards.date), 'awards.date must be a date');
  for (const group of ['awards', 'awards.year_to_date', 'awards.masked_suppliers']) {
    const totals = group === 'awards' ? awards : awards[group.split('.')[1]];
    expect(isObject(totals), `${group} must be an object`);
    if (isObject(totals)) {
      for (const field of ['count', 'total_gtq', 'total_usd']) {
        expect(isNumber(totals[field]), `${group}.${field} must be a number`);
      }
    }
  }
  if (isObject(awards.masked_suppliers)) {
    const largest = awards.masked_suppliers.largest_gtq;
    expect(largest === null || isNumber(largest), 'awards.masked_suppliers.largest_gtq must be a number or null');
  }
  expect(Array.isArray(awards.largest), 'awards.largest must be a list');
  for (const [index, award] of (Array.isArray(awards.largest) ? awards.largest : []).entries()) {
    expect(isText(award.supplier_name), `awards.largest[${index}].supplier_name must be text`);
    expect(isText(award.buyer_name), `awards.largest[${index}].buyer_name must be text`);
    expect(isNumber(award.amount_gtq), `awards.largest[${index}].amount_gtq must be a number`);
  }
}

expect(isObject(digest.row_counts), 'row_counts must be an object');
for (const [table, count] of Object.entries(isObject(digest.row_counts) ? digest.row_counts : {})) {
  expect(isNumber(count), `row_counts.${table} must be a number`);
}

return [{ json: { valid: errors.length === 0, errors, digest } }];

// An invalid payload was already refused in the answer to the webhook.
const { valid, digest } = $input.first().json;
if (!valid) return [];

// Settings come from the environment of the n8n container (see .env.example).
// A missing one stops the workflow, and the error workflow reports it.
const setting = (name) => {
  const value = $env[name];
  if (value === undefined || value === '') throw new Error(`${name} is not set`);
  return value;
};
const numberSetting = (name) => {
  const value = Number(setting(name));
  if (!Number.isFinite(value)) throw new Error(`${name} must be a number`);
  return value;
};
const money = (value) => value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const whole = (value) => value.toLocaleString('en-US');

// Checked here so that a missing recipient fails before anything is sent.
setting('NOTIFICATIONS_TELEGRAM_CHAT_ID');
setting('NOTIFICATIONS_EMAIL_FROM');
setting('NOTIFICATIONS_EMAIL_TO');
const rateThreshold = numberSetting('NOTIFICATIONS_RATE_CHANGE_ALERT_PERCENT');
const awardThreshold = numberSetting('NOTIFICATIONS_AWARD_ALERT_GTQ');

const rate = digest.exchange_rate;
const awards = digest.awards;
const signed = (value, digits) => (value > 0 ? '+' : '') + value.toFixed(digits);

const alerts = [];
if (rate && rate.change_percent !== null && Math.abs(rate.change_percent) > rateThreshold) {
  alerts.push(
    `The dollar rate moved ${signed(rate.change_percent, 2)} % from ${rate.previous_date}, ` +
    `more than the ${rateThreshold} % threshold.`
  );
}
for (const award of awards.largest.filter((a) => a.amount_gtq > awardThreshold)) {
  alerts.push(`An award of Q${money(award.amount_gtq)} to ${award.supplier_name} is above Q${money(awardThreshold)}.`);
}
// Masked suppliers are never named or ranked, so the alert does not give the
// amount either: with the buyer and the day it would point to the person.
const masked = awards.masked_suppliers;
if (masked.largest_gtq !== null && masked.largest_gtq > awardThreshold) {
  alerts.push(`At least one award to a masked supplier is above Q${money(awardThreshold)}; it is not detailed here.`);
}

const lines = [`Quetzal lakehouse - daily digest of ${digest.run_date}`, ''];
if (alerts.length) {
  lines.push('ALERTS', ...alerts.map((alert) => `- ${alert}`), '');
}

lines.push('Exchange rate');
if (rate) {
  lines.push(`${rate.date}: Q${rate.rate.toFixed(5)} per US dollar.`);
  if (rate.change !== null) {
    lines.push(`Change from ${rate.previous_date}: ${signed(rate.change, 5)} (${signed(rate.change_percent, 2)} %).`);
  }
  if (!rate.is_published) {
    lines.push(`The bank published no rate for this day; this is the rate of ${rate.rate_published_date}.`);
  }
} else {
  lines.push('No exchange rate in gold up to this day.');
}
lines.push('');

lines.push(`Awards of ${awards.date}`);
lines.push(`${whole(awards.count)} valid awards, Q${money(awards.total_gtq)} (US$${money(awards.total_usd)}).`);
lines.push(`Year to date: ${whole(awards.year_to_date.count)} awards, Q${money(awards.year_to_date.total_gtq)}.`);
lines.push(
  `To masked suppliers (natural persons or unknown legal type): ${whole(masked.count)} awards, ` +
  `Q${money(masked.total_gtq)}.`
);
if (awards.largest.length) {
  lines.push('', 'Largest awards to legal entities');
  awards.largest.forEach((award, index) => {
    lines.push(`${index + 1}. Q${money(award.amount_gtq)} - ${award.supplier_name}`);
    lines.push(`   ${award.buyer_name}, ${award.procurement_procedure}, process ${award.ocid}`);
  });
}
lines.push('');

lines.push('Rows in gold');
for (const [table, count] of Object.entries(digest.row_counts)) {
  lines.push(`${table}: ${whole(count)}`);
}
lines.push('', `Run: ${digest.run_id ?? 'not given'}`);

const subject = `Quetzal lakehouse: daily digest of ${digest.run_date}` + (alerts.length ? ' (alerts)' : '');
return [{ json: { subject, text: lines.join('\n'), alerts: alerts.length } }];

// Both channels are tried even when one fails, so one broken channel does
// not silence the other. A failure is raised here, after both, and the error
// workflow reports it.
const failures = [];
for (const node of ['Send to Telegram', 'Send email']) {
  const error = $(node).first().json.error;
  if (error) failures.push(`${node}: ${typeof error === 'string' ? error : JSON.stringify(error)}`);
}
if (failures.length) throw new Error(failures.join('; '));
return [{ json: { delivered: true } }];
